  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) throw new Fail('error: usage: cli.js normalize|resolve')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
